python3 << 'PYSCRIPT'
import csv, json, statistics, html

# Load data
rows = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append(r)

for r in rows:
    for k in ['cost_of_living_index','rent_index','cost_of_living_plus_rent_index','groceries_index',
              'restaurant_price_index','local_purchasing_power_index','petrol_price_usd_per_liter',
              'annual_inflation_rate_2025_pct','population_city_millions','rent_to_salary_ratio_pct']:
        r[k] = float(r[k])
    for k in ['rank','avg_monthly_net_salary_usd','monthly_rent_1br_city_center_usd',
              'monthly_rent_1br_outside_center_usd','cost_crisis_tier','data_year']:
        r[k] = int(r[k])

# KPIs
median_col = statistics.median([r['cost_of_living_index'] for r in rows])
avg_rts = statistics.mean([r['rent_to_salary_ratio_pct'] for r in rows])
ppp_vals = [r['local_purchasing_power_index'] for r in rows]
ppp_gap = max(ppp_vals) - min(ppp_vals)
max_tier = max(r['cost_crisis_tier'] for r in rows)
high_crisis_count = sum(1 for r in rows if r['cost_crisis_tier'] == max_tier)
avg_inflation = statistics.mean([r['annual_inflation_rate_2025_pct'] for r in rows])

# Regional aggregation
regions = {}
for r in rows:
    reg = r['region']
    if reg not in regions:
        regions[reg] = []
    regions[reg].append(r)

def reg_avg(cities, key):
    return statistics.mean([c[key] for c in cities])

# Sort regions by avg CoL descending
sorted_regions = sorted(regions.items(), key=lambda x: -reg_avg(x[1], 'cost_of_living_index'))

# Crisis tiers
tiers = {}
for r in rows:
    t = r['cost_crisis_tier']
    if t not in tiers:
        tiers[t] = []
    tiers[t].append(r)

# Oil shock
oil_groups = {}
for r in rows:
    o = r['oil_shock_exposure']
    if o not in oil_groups:
        oil_groups[o] = []
    oil_groups[o].append(r)

# Top/bottom rent burden
sorted_rts = sorted(rows, key=lambda x: -x['rent_to_salary_ratio_pct'])

# Top inflation
sorted_inf = sorted(rows, key=lambda x: -x['annual_inflation_rate_2025_pct'])

# Build regional outlier analysis
regional_outliers = []
for reg, cities in regions.items():
    if len(cities) < 3:
        continue
    avg_col = reg_avg(cities, 'cost_of_living_index')
    std_col = statistics.stdev([c['cost_of_living_index'] for c in cities]) if len(cities) > 1 else 0
    avg_rts_r = reg_avg(cities, 'rent_to_salary_ratio_pct')
    for c in cities:
        col_dev = c['cost_of_living_index'] - avg_col
        rts_dev = c['rent_to_salary_ratio_pct'] - avg_rts_r
        if abs(col_dev) > 15 or abs(rts_dev) > 5:
            regional_outliers.append({
                'city': c['city'], 'region': reg,
                'col_dev': col_dev, 'rts_dev': rts_dev,
                'col': c['cost_of_living_index'], 'rts': c['rent_to_salary_ratio_pct'],
                'reg_avg_col': avg_col, 'reg_avg_rts': avg_rts_r
            })

# Tier labels mapping
tier_names = {
    1: "Affluent / Low Cost-High Wage",
    2: "High Cost",
    3: "Moderate Cost / Transitional",
    4: "Low Income / Rising Pressure",
    5: "Severe Crisis"
}

# ============ HTML GENERATION ============

# Chart.js data prep
# 1. Regional bar chart data
reg_labels = [r[0] for r in sorted_regions]
reg_col_data = [round(reg_avg(r[1], 'cost_of_living_index'), 1) for r in sorted_regions]
reg_ppp_data = [round(reg_avg(r[1], 'local_purchasing_power_index'), 1) for r in sorted_regions]

# 2. Crisis tier radar-ish: use grouped bar
tier_labels_list = [f"Tier {t}" for t in sorted(tiers.keys())]
tier_col = [round(reg_avg(tiers[t], 'cost_of_living_index'), 1) for t in sorted(tiers.keys())]
tier_ppp = [round(reg_avg(tiers[t], 'local_purchasing_power_index'), 1) for t in sorted(tiers.keys())]
tier_salary = [round(reg_avg(tiers[t], 'avg_monthly_net_salary_usd'), 0) for t in sorted(tiers.keys())]
tier_rts = [round(reg_avg(tiers[t], 'rent_to_salary_ratio_pct'), 1) for t in sorted(tiers.keys())]
tier_inf = [round(reg_avg(tiers[t], 'annual_inflation_rate_2025_pct'), 1) for t in sorted(tiers.keys())]

# 3. Rent burden scatter: salary vs rent ratio
scatter_data = []
for r in rows:
    scatter_data.append({
        'x': r['avg_monthly_net_salary_usd'],
        'y': r['rent_to_salary_ratio_pct'],
        'label': r['city']
    })

# 4. Top 15 rent burden bar
top15_rts_labels = [r['city'] for r in sorted_rts[:15]]
top15_rts_vals = [r['rent_to_salary_ratio_pct'] for r in sorted_rts[:15]]

# 5. Oil shock grouped bar
oil_order = ['Low', 'Medium', 'High']
oil_col = [round(reg_avg(oil_groups[o], 'cost_of_living_index'), 1) for o in oil_order]
oil_inf = [round(reg_avg(oil_groups[o], 'annual_inflation_rate_2025_pct'), 1) for o in oil_order]
oil_ppp = [round(reg_avg(oil_groups[o], 'local_purchasing_power_index'), 1) for o in oil_order]

# 6. Top inflation cities
top10_inf_labels = [r['city'] for r in sorted_inf[:10]]
top10_inf_vals = [r['annual_inflation_rate_2025_pct'] for r in sorted_inf[:10]]

# Tier city count for donut
tier_counts = [len(tiers[t]) for t in sorted(tiers.keys())]

# Escape for JS
import json as J

def js(obj):
    return J.dumps(obj)

# Build regional comparison table rows
reg_table_rows = ""
for reg, cities in sorted_regions:
    n = len(cities)
    ac = round(reg_avg(cities, 'cost_of_living_index'), 1)
    ar = round(reg_avg(cities, 'rent_index'), 1)
    ap = round(reg_avg(cities, 'local_purchasing_power_index'), 1)
    asal = round(reg_avg(cities, 'avg_monthly_net_salary_usd'), 0)
    arts = round(reg_avg(cities, 'rent_to_salary_ratio_pct'), 1)
    ainf = round(reg_avg(cities, 'annual_inflation_rate_2025_pct'), 1)
    reg_table_rows += f"<tr><td>{reg}</td><td>{n}</td><td>{ac}</td><td>{ar}</td><td>{ap}</td><td>${asal:,.0f}</td><td>{arts}%</td><td>{ainf}%</td></tr>\n"

# Tier comparison table
tier_table_rows = ""
for t in sorted(tiers.keys()):
    cities = tiers[t]
    n = len(cities)
    labels = sorted(set(c['crisis_label'] for c in cities))
    ac = round(reg_avg(cities, 'cost_of_living_index'), 1)
    ar = round(reg_avg(cities, 'rent_index'), 1)
    ap = round(reg_avg(cities, 'local_purchasing_power_index'), 1)
    asal = round(reg_avg(cities, 'avg_monthly_net_salary_usd'), 0)
    arts = round(reg_avg(cities, 'rent_to_salary_ratio_pct'), 1)
    ainf = round(reg_avg(cities, 'annual_inflation_rate_2025_pct'), 1)
    tier_table_rows += f"<tr><td>Tier {t}</td><td>{tier_names[t]}</td><td>{n}</td><td>{ac}</td><td>{ar}</td><td>{ap}</td><td>${asal:,.0f}</td><td>{arts}%</td><td>{ainf}%</td></tr>\n"

# Tier city lists
tier_city_lists = ""
for t in sorted(tiers.keys()):
    cities = sorted(tiers[t], key=lambda x: x['rank'])
    tier_city_lists += f"<h4>Tier {t}: {tier_names[t]} ({len(cities)} cities)</h4><p>"
    tier_city_lists += ", ".join(f"{c['city']} ({c['country']})" for c in cities)
    tier_city_lists += "</p>"

# Affordability top 20 table
afford_table = ""
for r in sorted_rts[:20]:
    afford_table += f"<tr><td>{r['city']}</td><td>{r['country']}</td><td>{r['region']}</td><td>{r['rent_to_salary_ratio_pct']}%</td><td>${r['avg_monthly_net_salary_usd']:,}</td><td>${r['monthly_rent_1br_city_center_usd']:,}</td><td>{r['cost_of_living_index']}</td></tr>\n"

# Bottom 20 (lowest rent burden)
afford_table_bottom = ""
for r in sorted_rts[-15:]:
    afford_table_bottom += f"<tr><td>{r['city']}</td><td>{r['country']}</td><td>{r['region']}</td><td>{r['rent_to_salary_ratio_pct']}%</td><td>${r['avg_monthly_net_salary_usd']:,}</td><td>${r['monthly_rent_1br_city_center_usd']:,}</td><td>{r['cost_of_living_index']}</td></tr>\n"

# Regional outlier section
outlier_html = ""
for o in sorted(regional_outliers, key=lambda x: -abs(x['col_dev'])):
    direction_col = "above" if o['col_dev'] > 0 else "below"
    direction_rts = "above" if o['rts_dev'] > 0 else "below"
    outlier_html += f"<tr><td>{o['city']}</td><td>{o['region']}</td><td>{o['col']}</td><td>{o['reg_avg_col']:.1f}</td><td>{o['col_dev']:+.1f}</td><td>{o['rts']:.1f}%</td><td>{o['reg_avg_rts']:.1f}%</td><td>{o['rts_dev']:+.1f}</td></tr>\n"

# Inflation & oil table
oil_table = ""
for o in oil_order:
    cities = oil_groups[o]
    n = len(cities)
    ac = round(reg_avg(cities, 'cost_of_living_index'), 1)
    ainf = round(reg_avg(cities, 'annual_inflation_rate_2025_pct'), 1)
    ap = round(reg_avg(cities, 'local_purchasing_power_index'), 1)
    asal = round(reg_avg(cities, 'avg_monthly_net_salary_usd'), 0)
    oil_table += f"<tr><td>{o}</td><td>{n}</td><td>{ac}</td><td>{ainf}%</td><td>{ap}</td><td>${asal:,.0f}</td></tr>\n"

# Top 10 inflation table
inf_table = ""
for r in sorted_inf[:10]:
    inf_table += f"<tr><td>{r['city']}</td><td>{r['country']}</td><td>{r['annual_inflation_rate_2025_pct']}%</td><td>{r['cost_of_living_index']}</td><td>{r['local_purchasing_power_index']}</td><td>{r['oil_shock_exposure']}</td><td>Tier {r['cost_crisis_tier']}</td></tr>\n"

# Scatter data for Chart.js
tier_colors = {1: '#2ecc71', 2: '#3498db', 3: '#f39c12', 4: '#e67e22', 5: '#e74c3c'}
scatter_datasets = ""
for t in sorted(tiers.keys()):
    pts = [{'x': c['avg_monthly_net_salary_usd'], 'y': c['rent_to_salary_ratio_pct'], 'label': c['city']} for c in tiers[t]]
    scatter_datasets += f"""{{
        label: 'Tier {t}',
        data: {js([{'x':p['x'],'y':p['y']} for p in pts])},
        backgroundColor: '{tier_colors[t]}',
        pointRadius: 6,
        pointHoverRadius: 9,
    }},"""

# Full 80 city table for appendix
full_table = ""
for r in sorted(rows, key=lambda x: x['rank']):
    full_table += f"<tr><td>{r['rank']}</td><td>{r['city']}</td><td>{r['country']}</td><td>{r['region']}</td><td>{r['cost_of_living_index']}</td><td>{r['rent_index']}</td><td>{r['local_purchasing_power_index']}</td><td>${r['avg_monthly_net_salary_usd']:,}</td><td>{r['rent_to_salary_ratio_pct']}%</td><td>{r['annual_inflation_rate_2025_pct']}%</td><td>Tier {r['cost_crisis_tier']}</td></tr>\n"

# PPP min/max cities
ppp_max_city = max(rows, key=lambda x: x['local_purchasing_power_index'])
ppp_min_city = min(rows, key=lambda x: x['local_purchasing_power_index'])

# Most/least expensive
most_expensive = rows[0]  # rank 1
least_expensive = max(rows, key=lambda x: x['rank'])

# Highest/lowest rent burden
highest_rts = sorted_rts[0]
lowest_rts = sorted_rts[-1]

report_html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
